    71  void KCompressionDevicePrivate::propagateErrorCode()
    72  {
    73      QIODevice *dev = filter->device();
    74      if (QFileDevice *fileDev = qobject_cast<QFileDevice *>(dev)) {
    75          if (fileDev->error() != QFileDevice::NoError) {
    76              errorCode = fileDev->error();
    77              q->setErrorString(dev->errorString());
    78          }
    79      }
    80      // ... we have no generic way to propagate errors from other kinds of iodevices. Sucks, heh? :(
    81  }
