    83  KFilterBase *KCompressionDevice::filterForCompressionType(KCompressionDevice::CompressionType type)
    84  {
    85      switch (type) {
    86      case KCompressionDevice::GZip:
    87          return new KGzipFilter;
    88      case KCompressionDevice::BZip2:
    89  #if HAVE_BZIP2_SUPPORT
    90          return new KBzip2Filter;
    91  #else
    92          return nullptr;
    93  #endif
    94      case KCompressionDevice::Xz:
    95  #if HAVE_XZ_SUPPORT
    96          return new KXzFilter;
    97  #else
    98          return nullptr;
    99  #endif
   100      case KCompressionDevice::None:
   101          return new KNoneFilter;
   102      }
   103      return nullptr;
   104  }
