   144  bool KCompressionDevice::open(QIODevice::OpenMode mode)
   145  {
   146      if (isOpen()) {
   147          //qCWarning(KArchiveLog) << "KCompressionDevice::open: device is already open";
   148          return true; // QFile returns false, but well, the device -is- open...
   149      }
   150      if (!d->filter) {
   151          return false;
   152      }
   153      d->bOpenedUnderlyingDevice = false;
   154      //qCDebug(KArchiveLog) << mode;
   155      if (mode == QIODevice::ReadOnly) {
   156          d->buffer.resize(0);
   157      } else {
   158          d->buffer.resize(BUFFER_SIZE);
   159          d->filter->setOutBuffer(d->buffer.data(), d->buffer.size());
   160      }
   161      if (!d->filter->device()->isOpen()) {
   162          if (!d->filter->device()->open(mode)) {
   163              //qCWarning(KArchiveLog) << "KCompressionDevice::open: Couldn't open underlying device";
   164              d->propagateErrorCode();
   165              return false;
   166          }
   167          d->bOpenedUnderlyingDevice = true;
   168      }
   169      d->bNeedHeader = !d->bSkipHeaders;
   170      d->filter->setFilterFlags(d->bSkipHeaders ? KFilterBase::NoHeaders : KFilterBase::WithHeaders);
   171      if (!d->filter->init(mode)) {
   172          return false;
   173      }
   174      d->result = KFilterBase::Ok;
   175      setOpenMode(mode);
   176      return true;
   177  }
